<?php
namespace Modules\LeaveManagement\Controllers;
use App\Http\Controllers\ModuleBaseController;
use Illuminate\Http\Request;
use Modules\Unit\Models\Unit;
class LeaveUnitController extends ModuleBaseController { public function index(){return view('leave-management::feature',['section'=>'units','title'=>'Đơn vị quản lý phép','items'=>Unit::active()->with('parent')->withCount('instructors')->orderBy('name')->get(),'parents'=>Unit::active()->orderBy('name')->get()]);} public function store(Request $r){$d=$r->validate(['code'=>'required|string|max:80|unique:units,code','name'=>'required|string|max:255','parent_id'=>'nullable|exists:units,id','level'=>'nullable|integer|min:1','status'=>'required|in:active,inactive']);$d['created_by']=$r->user()->id;Unit::create($d);return back()->with('success','Đã thêm đơn vị.');} public function update(Request $r,Unit $unit){$d=$r->validate(['code'=>'required|string|max:80|unique:units,code,'.$unit->id,'name'=>'required|string|max:255','parent_id'=>'nullable|exists:units,id','level'=>'nullable|integer|min:1','status'=>'required|in:active,inactive']);$d['updated_by']=$r->user()->id;$unit->update($d);return back()->with('success','Đã cập nhật đơn vị.');} public function delete(Unit $unit){$hasClasses=\Modules\LeaveManagement\Models\LeaveClass::where('unit_id',$unit->id)->exists();$hasPersonnel=\Modules\LeaveManagement\Models\LeavePersonnel::where('unit_id',$unit->id)->exists();if($unit->children()->exists()||$unit->instructors()->exists()||$hasPersonnel||$hasClasses)return back()->withErrors(['unit'=>'Không thể xóa đơn vị đang có đơn vị con, lớp, nhân sự hoặc dữ liệu liên quan.']);$unit->delete();return back()->with('success','Đã xóa đơn vị.');} public function import(Request $r){$r->validate(['file'=>'required|file|mimes:xlsx,xls,csv,txt|max:20480']);$rows=\PhpOffice\PhpSpreadsheet\IOFactory::load($r->file('file')->getRealPath())->getActiveSheet()->toArray(null,true,true,true);$headers=array_map(fn($v)=>strtolower(trim((string)$v)),array_shift($rows));$count=0;foreach($rows as $row){$v=[];foreach($headers as $key=>$header)$v[$header]=trim((string)($row[$key]??''));if(($v['code']??'')===''||($v['name']??'')==='')continue;$parent=($v['parent_code']??'')!==''?Unit::where('code',$v['parent_code'])->first():null;Unit::updateOrCreate(['code'=>$v['code']],['name'=>$v['name'],'parent_id'=>$parent?->id,'level'=>(int)($v['level']??1),'status'=>$v['status']??'active','updated_by'=>$r->user()->id]);$count++;}return back()->with('success',"Đã import {$count} đơn vị.");} public function seed(){return back()->with('success','Đã đồng bộ với danh sách đơn vị hệ thống.');} }
